518	    fn find_canonical_editor(&self, workspace: &Workspace, cx: &App) -> Option<Entity<Editor>> {
519	        let current = self.active_editor.as_ref()?.editor.clone();
520	        let our_buffer = current.read(cx).buffer().read(cx).as_singleton()?;
